'use strict';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={role:localStorage.getItem('cp_role')||'professor',page:'dashboard',courseId:0,tab:'all',data:null,studentName:localStorage.getItem('cp_student')||'Sample Student',studentCourses:JSON.parse(localStorage.getItem('cp_joined')||'[]'),chat:[],busy:false,contentTab:'syllabus',officeDay:0,canvasMapping:JSON.parse(localStorage.getItem('cp_canvas_mapping')||'{}'),theme:localStorage.getItem('cp_theme')||'light',canvasStatus:{configured:false,connected:false},canvasCourses:[],canvasAssignments:[],canvasCourseId:'',canvasBusy:false,studentTab:'overview'};
document.documentElement.dataset.theme=state.theme;
const byCourse=(list)=>list.filter(x=>x.course_id===state.courseId);
const course=()=>state.data.courses.find(c=>c.id===state.courseId);
const sectionLabel=c=>`${c.course_code||c.code} · Section ${c.section||'001'}`;
const official=()=>state.data.syllabi?.find(s=>s.course_id===state.courseId);
const fmt=d=>new Date(d).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
const toast=msg=>{$('toastRoot').innerHTML=`<div class="toast">${esc(msg)}</div>`;setTimeout(()=>$('toastRoot').innerHTML='',3500)};
const mk=(s)=>`<span class="muted">${esc(s)}</span>`;
async function api(path,body){const r=await fetch('/api/'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(data.error||'Request failed');return data}
async function load(){try{state.data=await api('state');if(!state.courseId||!state.data.courses.some(c=>c.id===state.courseId))state.courseId=state.data.courses[0]?.id||0;if(state.role==='student'&&state.page==='dashboard')state.page='studentHome';render()}catch(e){$('view').innerHTML=`<div class="card"><h2>Could not load the application</h2><p>Start the local Python server using <code>python3 server.py</code>, then open http://127.0.0.1:8000.</p><div class="note">${esc(e.message)}</div></div>`}}
const counts=()=>({classes:state.data.courses.length,materials:state.data.materials.length,faqs:state.data.faqs.length,students:state.data.enrollments.length,questions:state.data.activity.filter(a=>a.event==='assistant_question').length});
function heading(eyebrow,title,sub,actions=''){return `<div class="intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${actions}</div>`}
function button(label,action,cls=''){return `<button class="btn ${cls}" data-action="${action}">${label}</button>`}
function stat(label,value,icon,foot){return `<div class="card"><span class="stat-icon">${icon}</span><div class="statlabel">${label}</div><div class="statvalue">${value}</div><div class="statfoot">${foot}</div></div>`}
function selected(){return `<select class="course-select" id="courseSelect" aria-label="Selected course">${state.data.courses.map(c=>`<option value="${c.id}" ${c.id===state.courseId?'selected':''}>${esc(sectionLabel(c))} · ${esc(c.name)}</option>`).join('')}</select>`}
function nav(){
 const items=state.role==='professor'?
 [['dashboard','▦','Overview'],['courses','▤','Sections'],['content','▣','Course Knowledge'],['office','▦','Office Hours'],['codes','⌗','Students & Access'],['analytics','▥','Insights'],['profile','♙','Profile']]:
 [['studentHome','▦','Dashboard'],['student','▤','My Sections'],['assistant','✦','Course Assistant'],['studentCanvas','⇄','Canvas & Tasks']];
 $('nav').innerHTML=items.map(([id,ico,label])=>`<button class="${state.page===id?'active':''}" data-page="${id}"><span class="icon">${ico}</span><span class="label">${label}</span></button>`).join('');
 $('roleBtn').textContent=state.role==='professor'?'⇄ Student view':'⇄ Professor view';
 $('crumb').textContent=state.role==='professor'?'Professor Workspace':'Student Workspace';
 $('avatar').textContent=state.role==='professor'?'PR':'ST';
 $('themeBtn').textContent=state.theme==='dark'?'☀ Light':'☾ Dark';
}
function content(){const tabs=[['syllabus','Official Syllabus','▣'],['materials','Resources','▧'],['faq','FAQs','☷']];return `<div class="hub-bar"><span class="hub-label">Course knowledge</span><div class="hub-switch">${tabs.map(([t,label,ico])=>`<button class="hub-tab ${state.contentTab===t?'active':''}" data-contenttab="${t}">${ico} ${label}</button>`).join('')}</div></div>`+(state.contentTab==='syllabus'?syllabus():state.contentTab==='materials'?materials():faq())}
function render(){if(!state.data)return;nav();const pages=state.role==='professor'?{dashboard,courses,content,office,codes,analytics,profile}:{studentHome,student,studentDetail:()=>{const c=state.data.courses.find(x=>x.id===state.courseId);return c?studentCourse(c):student()},assistant,studentCanvas:studentCanvasPage};$('view').innerHTML=(pages[state.page]||pages[state.role==='professor'?'dashboard':'studentHome'])()}
function goContent(tab){state.contentTab=tab;state.page='content';render()}
function dashboard(){const c=counts();let acts=state.data.activity.filter(a=>a.course_id===state.courseId).slice(0,5);return heading('Instructor workspace','Good morning, Professor 👋','Your sections, student activity, and teaching resources at a glance.',button('＋ Add section','course',''))+`<div class="cards">${stat('Active sections',c.classes,'▤','This semester')}${stat('Enrolled students',c.students,'♙','Demo enrollments')}${stat('AI knowledge items',c.materials,'▧','Across all courses')}${stat('Student questions',c.questions,'✦','Tracked demo activity')}</div><div class="layout"><section class="card"><div class="sectionhead"><h2>Your sections</h2><button class="linkbtn" data-page="courses">Manage sections →</button></div>${state.data.courses.map(x=>`<button class="course-tile" data-selectcourse="${x.id}" data-next="content"><span class="course-icon" style="color:${esc(x.color)}">${esc((x.course_code||x.code).slice(0,2))}</span><span style="flex:1"><strong>${esc(sectionLabel(x))}</strong><div class="muted">${esc(x.name)} · ${esc(x.term)}</div></span><span class="badge-circle">${state.data.materials.filter(m=>m.course_id===x.id).length} items</span></button>`).join('')||'<div class="empty">Add your first section to get started.</div>'}</section><div><section class="card"><div class="sectionhead"><h2>Quick actions</h2></div><div class="actions"><button class="btn secondary" data-contenttab="syllabus" data-openknowledge="1">▣ Course knowledge</button>${button('⌗ Invite students','code','secondary')}</div><div class="note" style="margin-top:17px">Select a section at the top of each page to keep materials, FAQs, and class codes organized by section.</div></section><section class="card" style="margin-top:18px"><div class="sectionhead"><h2>Recent activity</h2><button class="linkbtn" data-page="analytics">View analytics →</button></div>${state.data.activity.slice(0,4).map(a=>`<div class="listrow"><div><strong>${a.event==='assistant_question'?'Student asked a question':a.event==='faq_view'?'FAQ viewed':'Course material opened'}</strong><div class="muted">${esc(a.subject.slice(0,65))}</div></div><span class="tag">${fmt(a.created_at)}</span></div>`).join('')||'<div class="empty">No activity yet.</div>'}</section></div></div>`}
function courses(){return heading('Section management','My sections','Manage multiple sections of the same course independently.',button('＋ Add section','course'))+`<div class="cards" style="grid-template-columns:repeat(auto-fit,minmax(245px,1fr))">${state.data.courses.map(c=>`<section class="card"><div class="course-icon" style="margin-bottom:16px">${esc((c.course_code||c.code).slice(0,2))}</div><h2>${esc(sectionLabel(c))}</h2><p>${esc(c.name)}<br>${esc(c.term)}</p><div class="muted">${state.data.enrollments.filter(e=>e.course_id===c.id).length} enrolled students · ${state.data.materials.filter(m=>m.course_id===c.id).length} materials</div><div class="actions" style="margin-top:18px"><button class="btn secondary small" data-selectcourse="${c.id}" data-next="content">Manage →</button><button class="btn ghost small" data-selectcourse="${c.id}" data-next="codes">Class codes</button><button class="btn danger small" data-delete="course:${c.id}">Delete</button></div></section>`).join('')||'<div class="card">No classes yet.</div>'}</div>`}
const kinds=[['all','All'],['resource','Links'],['document','Files'],['contact','Contacts'],['notes','Notes']];
function materials(){const items=byCourse(state.data.materials).filter(m=>kinds.some(k=>k[0]===m.kind)&&(state.tab==='all'||m.kind===state.tab));return heading('Course knowledge','Supplemental resources','Helpful links, contacts, and optional materials—not a replacement for Canvas.',`<div class="actions">${selected()}${button('＋ Add resource','material')}${button('↑ Upload supplement','upload','secondary')}</div>`)+`<div class="note" style="margin-bottom:18px">The official Simple Syllabus is the primary source for policies and course information. Assignments, modules, grades and lecture schedules stay in Canvas. Add only resources that improve student support.</div><div class="tabs">${kinds.map(([key,label])=>`<button class="tab ${state.tab===key?'active':''}" data-tab="${key}">${label}</button>`).join('')}</div><div class="layout"><section class="card"><div class="sectionhead"><h2>${state.tab==='all'?'Supplemental knowledge':kinds.find(k=>k[0]===state.tab)?.[1]} <small>(${items.length})</small></h2></div>${items.map(m=>`<div class="resource"><div class="sectionhead"><h3>${esc(m.title)}</h3><span class="tag">${esc(m.kind.replace('_',' '))}</span></div><p>${esc(m.body.slice(0,240))}${m.body.length>240?'…':''}</p>${m.url?`<a href="${esc(m.url)}" target="_blank" rel="noopener noreferrer">Open resource ↗</a>`:''}<div class="actions"><button class="linkbtn" data-detail="${m.id}">View</button><button class="linkbtn" style="color:#d25a66" data-delete="material:${m.id}">Remove</button></div></div>`).join('')||'<div class="empty">Nothing additional needed yet. The official syllabus and Canvas remain your main sources.</div>'}</section><aside class="card"><h2>What belongs here?</h2><p>Optional practice sites, YouTube guides, tutoring centers, external readings, and contact instructions.</p><div class="listrow">🎬 &nbsp;YouTube tutorials</div><div class="listrow">🔗 &nbsp;Practice websites</div><div class="listrow">📘 &nbsp;Supplemental notes</div><div class="listrow">✉ &nbsp;Support contacts</div><div class="note" style="margin-top:18px">Links are stored and displayed; videos are not transcribed automatically.</div></aside></div>`}
function syllabus(){const f=official();const details=f?.details||{};return heading('Primary source of truth','Official Simple Syllabus','Import the PDF using Simple Syllabus → Print → Save as PDF.',`<div class="actions">${selected()}${button(f?'↻ Replace syllabus':'↑ Import official PDF','syllabus')}</div>`)+`<div class="layout"><section class="card"><div class="sectionhead"><h2>${f?'Official syllabus imported':'No official syllabus yet'}</h2><span class="tag">${f?`${f.page_count} pages indexed`:'Upload required'}</span></div>${f?`<div class="resource"><strong>▣ ${esc(f.filename)}</strong><p>Imported ${fmt(f.imported_at)} · Primary imported document source</p>${f.source_url?`<a href="${esc(f.source_url)}" target="_blank" rel="noopener noreferrer">Open Simple Syllabus ↗</a>`:''}</div><div class="formgrid">${[['Instructor',details.instructor],['Instructor email',details.email],['Office location',details.office],['Official office hours',details.office_hours]].map(([k,v])=>`<div class="resource"><div class="muted">${k}</div><strong>${esc(v||'Refer to the PDF')}</strong></div>`).join('')}</div>${details.grading_weights?.length?`<div class="resource" style="margin-top:16px"><strong>Grading breakdown · from syllabus page 5</strong>${details.grading_weights.map(x=>`<div class="listrow">${esc(x)}</div>`).join('')}</div>`:''}<div class="actions" style="margin-top:16px">${button('↻ Replace PDF','syllabus','secondary')}<button class="btn danger small" data-delete="syllabus:${f.id}">Remove syllabus</button></div>`:`<div class="empty"><div style="font-size:36px">▣</div><h2>One official syllabus per section</h2><p>Use the university-approved Simple Syllabus printout. The assistant uses its content ahead of informal FAQs for policies, grading and deadlines.</p>${button('↑ Import PDF','syllabus')}</div>`}</section><aside class="card"><h2>Import steps</h2><div class="listrow">1. Open your official Simple Syllabus page</div><div class="listrow">2. Select Print → Save as PDF</div><div class="listrow">3. Import PDF here for this section</div><div class="listrow">4. Review extracted details and pages</div><div class="note" style="margin-top:16px">Syllabus-only uploads are validated for Simple Syllabus markings. Replacing a syllabus overwrites the previous version for this section. Course schedules may change; live Canvas information should be checked for updates.</div></aside></div>`}
const weekdays=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
function office(){
 const slots=byCourse(state.data.office_hours||[]);
 const preference=state.data.office_settings?.find(x=>x.course_id===state.courseId);
 const mode=preference?.mode||'syllabus';
 const byAppointment=mode==='appointment'||(mode==='syllabus'&&/appointment/i.test(official()?.details?.office_hours||''));
 const noted=official()?.details?.office_hours||'No office hours listed. Import an official syllabus or choose a format.';
 const day=state.officeDay;
 const focusSlots=slots.filter(x=>x.weekday===day);
 return heading('Availability','Office hours','Give students one clear place to find your schedule and how to meet with you.',selected())+
 `<div class="office-layout"><section class="card office-main"><div class="sectionhead"><div><h2>How can students meet you?</h2><p class="smallinfo">Choose the schedule format for this section.</p></div><span class="tag">${byAppointment?'By appointment':mode==='weekly'?'Weekly hours':'From syllabus'}</span></div><div class="mode-picker"><button data-office-mode="appointment" class="mode-card ${byAppointment?'active':''}"><span class="mode-icon">◷</span><strong>By appointment</strong><small>Students request a meeting or use your booking link.</small></button><button data-office-mode="weekly" class="mode-card ${mode==='weekly'?'active':''}"><span class="mode-icon">▦</span><strong>Recurring hours</strong><small>Pick days and times from a weekly schedule.</small></button></div>
 ${byAppointment?`<div class="appointment-hero"><span class="appoint-symbol">◷</span><div><h2>Office hours by appointment</h2><p>${esc(preference?.instructions||'Students should contact the instructor to arrange an available time.')}</p>${preference?.booking_url?`<a href="${esc(preference.booking_url)}" rel="noopener noreferrer" target="_blank">Open booking link ↗</a>`:''}</div></div><div class="actions">${button('✎ Edit booking details','appointment','secondary')}</div>`:
 `<div class="calendar-header"><div><h2>Your weekly schedule</h2><p class="smallinfo">Select a day to view or add time slots.</p></div>${button('＋ Add availability','hours')}</div><div class="week-strip">${weekdays.map((name,i)=>{const dayslots=slots.filter(x=>x.weekday===i);return `<button class="weekday ${i===day?'active':''}" data-office-day="${i}"><span>${name.slice(0,3)}</span><strong>${dayslots.length?dayslots.length+' slot'+(dayslots.length>1?'s':''):'＋'}</strong></button>`}).join('')}</div><div class="day-agenda"><div class="sectionhead"><h3>${weekdays[day]}</h3><span class="muted">${focusSlots.length} available time slots</span></div>${focusSlots.length?focusSlots.map(x=>`<div class="appointment-row"><span class="time-block">${clock(x.start_time)} – ${clock(x.end_time)}</span><div class="grow"><strong>${esc(x.meeting_type)}</strong><div class="muted">${esc(x.location||'Location to be confirmed')}</div></div>${x.booking_url?`<a href="${esc(x.booking_url)}" target="_blank" rel="noopener noreferrer">Booking ↗</a>`:''}<button class="icon-remove" title="Remove this slot" aria-label="Remove this slot" data-delete="office_hours:${x.id}">✕</button></div>`).join(''):`<div class="empty-day"><span>◷</span><strong>No hours on ${weekdays[day]}</strong><p>Set your first time slot for this day.</p><button class="btn secondary" data-action="hours">＋ Add ${weekdays[day]} hours</button></div>`}</div>`}
 </section><aside class="card office-side"><div class="source-header">▣ Official source</div><h2>Simple Syllabus</h2><p>Office hours listed in your university syllabus:</p><div class="official-value">${esc(noted)}</div><p class="smallinfo">This is the authoritative course policy. Use the scheduler to show actual availability or a booking method.</p><button class="btn ghost" data-action="openSyllabus">View syllabus →</button><div class="soft-divider"></div><h3>Student preview</h3><p class="smallinfo">${byAppointment?'Students see how to request a meeting, rather than an empty calendar.':'Students see recurring weekly hours for the selected section.'}</p></aside></div>`;
}
function clock(value){const [h,m]=value.split(':').map(Number);return `${(h%12)||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`}
function dueDate(x){if(!x)return 'No due date';const d=new Date(x);return Number.isNaN(d.getTime())? 'No due date':d.toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}
async function syncCanvas(){state.canvasBusy=true;render();try{const status=await api('canvas/status');state.canvasStatus=status;if(status.connected){const r=await api('canvas/courses');state.canvasCourses=r.courses||[];if(!state.canvasCourses.some(c=>c.id===state.canvasCourseId))state.canvasCourseId=state.canvasCourses[0]?.id||'';if(state.canvasCourseId){const a=await api('canvas/assignments?course_id='+encodeURIComponent(state.canvasCourseId));state.canvasAssignments=a.assignments||[]}else state.canvasAssignments=[];}else{state.canvasCourses=[];state.canvasAssignments=[]}}catch(e){toast('Canvas: '+e.message)}finally{state.canvasBusy=false;render()}}
async function canvasChoose(id){state.canvasCourseId=id;state.canvasBusy=true;render();try{const a=await api('canvas/assignments?course_id='+encodeURIComponent(id));state.canvasAssignments=a.assignments||[]}catch(e){state.canvasAssignments=[];toast(e.message)}finally{state.canvasBusy=false;render()}}
function canvasTaskRows(items){return items.map(a=>`<div class="listrow"><div><strong>${esc(a.name)}</strong><div class="muted">Due ${esc(dueDate(a.due_at))} · ${a.points_possible==null?'Points not listed':esc(a.points_possible)+' points'}</div></div><a class="btn ghost small" href="${esc(a.url)}" rel="noopener noreferrer" target="_blank">Open in Canvas ↗</a></div>`).join('')||'<div class="empty">No published assignments found for this Canvas course.</div>'}
function studentCanvasPage(){const status=state.canvasStatus;const connected=status.connected;const items=state.canvasAssignments.slice().sort((a,b)=>(a.due_at||'9999').localeCompare(b.due_at||'9999'));return heading('Student tools','Canvas & Tasks','Read-only Canvas assignments, with the original course links for submissions and grades.',`<div class="actions">${connected?button(state.canvasBusy?'Refreshing…':'↻ Refresh','canvasRefresh','secondary')+button('Disconnect','canvasDisconnect','ghost'):''}</div>`)+`<div class="layout"><section class="card"><div class="sectionhead"><h2>${connected?'My Canvas assignments':'Connect your Canvas account'}</h2><span class="tag">${connected?'Connected · read-only':status.configured?'OAuth available':'Setup required'}</span></div>${!connected?`<div class="empty" style="padding:28px 15px"><span style="font-size:36px">⇄</span><h2 style="margin-top:12px">Bring Canvas deadlines into AnyHour</h2><p>Sign in through your institution's Canvas authorization screen. You control what you connect.</p>${status.configured?'<a class="btn" href="/api/canvas/connect">Connect with Canvas ↗</a>':'<div class="note">An administrator-approved Canvas developer key is required. The project owner must configure OAuth in the server before students can connect.</div>'}</div>`:`<div class="field"><label for="canvasCoursePicker">Canvas course</label><select id="canvasCoursePicker">${state.canvasCourses.map(c=>`<option value="${esc(c.id)}" ${c.id===state.canvasCourseId?'selected':''}>${esc(c.code||c.name)} · ${esc(c.name)}</option>`).join('')}</select></div>${state.canvasBusy?'<div class="empty">Loading assignments…</div>':canvasTaskRows(items)}<div class="note" style="margin-top:18px">Canvas is authoritative for due dates, submissions, grades, and assignment details. AnyHour reads the current assignments; changes must be made in Canvas.</div>`}</section><aside class="card"><h2>How it works</h2><div class="listrow"><div><strong>1. Connect securely</strong><div class="muted">Canvas grants read-only access through your university.</div></div></div><div class="listrow"><div><strong>2. View deadlines</strong><div class="muted">Browse the current assignments for one selected Canvas course.</div></div></div><div class="listrow"><div><strong>3. Ask AnyHour</strong><div class="muted">Use your professor's official syllabus, FAQs, and resources for explanations.</div></div></div>${connected?`<div class="soft-divider"></div><h3>Match your AnyHour sections</h3><p class="smallinfo">Optional: link a joined professor section to its Canvas course so the assistant can reference current assignment due dates.</p>${state.data.courses.filter(x=>state.studentCourses.includes(x.id)).map(c=>`<div class="field"><label>${esc(sectionLabel(c))}</label><select data-map-section="${c.id}"><option value="">Not matched</option>${state.canvasCourses.map(cc=>`<option value="${esc(cc.id)}" ${state.canvasMapping[c.id]===cc.id?'selected':''}>${esc(cc.code||cc.name)}</option>`).join('')}</select></div>`).join('')}`:''}<div class="soft-divider"></div><h3>Private & temporary</h3><p class="smallinfo">This local demo stores OAuth tokens only in server memory, not browser storage or the course database. Disconnect clears them. Accounts and access control are still needed before a real deployment.</p>${connected?`<span class="pill">${esc(status.canvas_domain||'Canvas connected')}</span>`:''}</aside></div>`}
function codes(){const all=byCourse(state.data.codes);return heading('Section access','Students & access','Manage section enrollment and share invitation codes.',`<div class="actions">${selected()}${button('＋ Generate section code','code')}</div>`)+`<div class="layout"><section class="card"><div class="sectionhead"><h2>Generated codes</h2><span class="tag">${all.filter(x=>x.active&&new Date(x.expires_at)>new Date()).length} active</span></div>${all.map(x=>{const active=x.active&&new Date(x.expires_at)>new Date();return `<div class="listrow"><div><strong>Section code ending ••••${esc(x.hint)}</strong><div class="muted">Created ${fmt(x.created_at)} · Expires ${fmt(x.expires_at)}</div></div><div class="actions"><span class="${active?'pill':'tag'}">${active?'Active':'Expired / revoked'}</span>${active?`<button class="btn danger small" data-revoke="${x.id}">Revoke</button>`:''}</div></div>`}).join('')||'<div class="empty">No codes generated yet.</div>'}<div class="note" style="margin-top:15px">For security, full codes are shown only when created. Generate a new code if you lose one.</div></section><aside class="card"><h2>Enrolled students</h2><p class="smallinfo">Student names for this section (${byCourse(state.data.enrollments).length})</p>${byCourse(state.data.enrollments).map(x=>`<div class="listrow"><strong>${esc(x.student_name)}</strong><span class="tag">Joined</span></div>`).join('')||'<div class="empty">No enrollments yet.</div>'}<div class="soft-divider"></div><h2>How it works</h2><p style="font-size:12px">Generate a random section code, share it with students, and tell them to use <strong>Join Class</strong> on the student side.</p><p style="font-size:12px">Each code has an expiration date, and you can revoke it at any time.</p><div class="note">This demo validates codes on the server, but it does not yet have account authentication or verified enrollment identity.</div></aside></div>`}
function faq(){const items=byCourse(state.data.faqs);return heading('Course knowledge','Frequently asked questions','Add approved, hard-coded answers that students receive instantly.',`<div class="actions">${selected()}${button('＋ Add FAQ','faq')}</div>`)+`<div class="layout"><section class="card"><div class="sectionhead"><h2>Approved answers</h2><span class="tag">${items.length} questions</span></div>${items.map(x=>`<div class="resource"><div class="sectionhead"><h3>${esc(x.question)}</h3><span class="pill">Verified answer</span></div><p style="color:#546680">${esc(x.answer)}</p><button class="linkbtn" style="color:#d25a66" data-delete="faq:${x.id}">Delete answer</button></div>`).join('')||'<div class="empty">No FAQs yet. Add one for common student questions.</div>'}</section><aside class="card"><h2>Why add FAQs?</h2><p style="font-size:12px">The assistant checks FAQ answers before searching other course material. This helps keep responses consistent with your expectations.</p><div class="note">Examples: late submission rules, group assignments, accepted programming languages, office hours, grading policies, and where to submit work.</div></aside></div>`}
function analytics(){const a=byCourse(state.data.activity),qa=a.filter(x=>x.event==='assistant_question'),views=a.filter(x=>x.event==='material_view'),faqs=a.filter(x=>x.event==='faq_view');let topics=[['Deadlines',/due|deadline|late|submit/i],['Projects & homework',/project|homework|assignment|lab/i],['Office hours',/office|help|email/i],['Tests & exams',/test|exam|quiz|study/i],['Other',/.*/]];let topicCount=topics.map(([n,pattern],i)=>({label:n,value:qa.filter(x=>pattern.test(x.subject)&&(i===4?!topics.slice(0,4).some(t=>t[1].test(x.subject)):true)).length}));const max=Math.max(1,...topicCount.map(x=>x.value));return heading('Teaching insights','Student activity analytics','See recurring questions and understand what students are using.',selected())+`<div class="cards">${stat('Student questions',qa.length,'✦','AI assistant requests')}${stat('Materials opened',views.length,'▧','Resource interactions')}${stat('FAQs viewed',faqs.length,'☷','Approved answers')}${stat('Enrolled students',byCourse(state.data.enrollments).length,'♙','This section')}</div><div class="layout"><section class="card"><div class="sectionhead"><h2>What students ask about</h2><span class="tag">Demo data</span></div>${topicCount.map(x=>`<div class="barrow"><span class="barlabel">${x.label}</span><div class="meter"><div style="width:${x.value/max*100}%"></div></div><strong>${x.value}</strong></div>`).join('')}</section><aside class="card"><div class="sectionhead"><h2>Recent questions</h2></div>${qa.slice(0,7).map(x=>`<div class="listrow"><div><strong>${esc(x.subject)}</strong><div class="muted">${fmt(x.created_at)}</div></div></div>`).join('')||'<div class="empty">No questions recorded yet.</div>'}</aside></div><div class="note" style="margin-top:18px">Analytics here are demo interaction counts, not verified real-world learning metrics. Production analytics should aggregate student activity and include privacy controls.</div>`}
function profile(){const p=state.data.profile;return heading('Account settings','Professor profile','Manage the instructor details presented to your students.')+`<div class="layout"><section class="card"><form id="profileForm"><div class="formgrid"><div class="field"><label for="full_name">Full name</label><input id="full_name" required maxlength="100" value="${esc(p.full_name)}"></div><div class="field"><label for="email">Email</label><input id="email" type="email" required maxlength="150" value="${esc(p.email)}"></div></div><div class="formgrid"><div class="field"><label for="department">Department</label><input id="department" maxlength="150" value="${esc(p.department)}"></div><div class="field"><label for="institution">Institution</label><input id="institution" maxlength="150" value="${esc(p.institution)}"></div></div><div class="field"><label for="bio">About you</label><textarea id="bio" maxlength="1200">${esc(p.bio)}</textarea></div><button type="submit" class="btn">Save profile</button></form></section><aside class="card"><div class="course-icon" style="width:62px;height:62px;border-radius:50%;font-size:23px;margin-bottom:17px">${esc(p.full_name.split(/\s+/).map(x=>x[0]).slice(-2).join(''))}</div><h2>${esc(p.full_name)}</h2><p>${esc(p.department)}<br>${esc(p.institution)}</p><span class="pill">Instructor</span><div class="note" style="margin-top:18px">This is a shared demonstration profile. In production, profiles and permissions would be tied to a verified instructor login.</div></aside></div>`}
function studentHome(){const joined=state.data.courses.filter(c=>state.studentCourses.includes(c.id)),q=state.data.faqs.filter(f=>joined.some(c=>c.id===f.course_id)),res=state.data.materials.filter(m=>joined.some(c=>c.id===m.course_id));return heading('Student workspace','Your learning hub 👋','Everything your professors have approved, organized by section.',`<div class="actions">${button('✦ Ask a question','assistant','secondary')}${button('＋ Join section','join')}</div>`)+`<div class="cards">${stat('My sections',joined.length,'▤','Professor-managed')}${stat('Approved FAQs',q.length,'☷','Instant answers')}${stat('Learning resources',res.length,'▧','Provided by instructors')}${stat('Canvas',state.canvasStatus.connected?'Connected':'Not connected','⇄','Student-controlled')}</div><div class="layout"><section class="card"><div class="sectionhead"><h2>Your sections</h2><button class="linkbtn" data-page="student">View all →</button></div>${joined.map(c=>`<button class="course-tile" data-studentcourse="${c.id}"><span class="course-icon">${esc((c.course_code||c.code).slice(0,2))}</span><span style="flex:1"><strong>${esc(sectionLabel(c))}</strong><span class="muted">${esc(c.name)}</span></span><span>→</span></button>`).join('')||'<div class="empty">Join a section with your professor’s code to get started.</div>'}</section><aside class="card"><h2>Quick access</h2><p>Get support without recreating Canvas.</p><div class="listrow"><button class="btn secondary" data-page="assistant">✦ Ask the course assistant</button></div><div class="listrow"><button class="btn secondary" data-page="studentCanvas">⇄ Canvas assignments</button></div><div class="note" style="margin-top:16px">The official Simple Syllabus is the source of truth for academic policies. Your professor maintains FAQs and office hours.</div></aside></div>`}
function student(){const joined=state.data.courses.filter(c=>state.studentCourses.includes(c.id));return heading('My learning space','My sections','Open the professor-approved syllabus, resources, FAQs, and office hours for each section.',`<div class="actions">${button('＋ Join a section','join')}</div>`)+`<div class="cards" style="grid-template-columns:repeat(auto-fit,minmax(245px,1fr))">${joined.map(c=>`<div class="card"><span class="course-icon">${esc((c.course_code||c.code).slice(0,2))}</span><h2 style="margin:14px 0 4px">${esc(sectionLabel(c))}</h2><p>${esc(c.name)} · ${esc(c.term)}</p><div class="actions"><button class="btn secondary" data-studentcourse="${c.id}">Open section →</button><button class="btn ghost small" data-visit="assistant:${c.id}">Ask assistant</button></div></div>`).join('')||'<div class="card"><h2>No sections joined yet</h2><p>Ask your professor for a section code to unlock their materials and assistant.</p></div>'}</div>`}
function studentCourse(c){const ms=state.data.materials.filter(m=>m.course_id===c.id),fs=state.data.faqs.filter(f=>f.course_id===c.id),sy=state.data.syllabi?.find(s=>s.course_id===c.id),pref=state.data.office_settings?.find(x=>x.course_id===c.id),slots=state.data.office_hours.filter(x=>x.course_id===c.id),src=sy?.details?.office_hours;const officeInfo=pref?.mode==='appointment'||(pref?.mode!=='weekly'&&/appointment/i.test(src||''))?`By appointment${pref?.instructions?' — '+pref.instructions:''}`:slots.length?slots.map(x=>weekdays[x.weekday]+' '+clock(x.start_time)+'–'+clock(x.end_time)).join(' · '):src||'Ask your instructor for availability';const tabs=[['overview','Overview'],['faqs','FAQs'],['resources','Resources'],['hours','Office hours']];return heading('My sections',`${esc(sectionLabel(c))}` ,esc(c.name),`<div class="actions">${button('✦ Ask assistant','assistant','secondary')}<button class="btn ghost" data-page="studentCanvas">Canvas & Tasks ↗</button></div>`)+`<div class="tabs">${tabs.map(([id,t])=>`<button class="tab ${state.studentTab===id?'active':''}" data-student-tab="${id}">${t}</button>`).join('')}</div>`+(state.studentTab==='overview'?`<div class="layout"><section class="card"><div class="sectionhead"><h2>Official Simple Syllabus</h2><span class="tag">${sy?sy.page_count+' pages':'Not uploaded'}</span></div>${sy?`<p><strong>${esc(sy.filename)}</strong></p><div class="formgrid"><div class="resource"><span class="muted">Instructor</span><strong>${esc(sy.details?.instructor||'See syllabus')}</strong></div><div class="resource"><span class="muted">Email</span><strong>${esc(sy.details?.email||'See syllabus')}</strong></div></div>${sy.source_url?`<a href="${esc(sy.source_url)}" target="_blank" rel="noopener noreferrer">Read official syllabus ↗</a>`:''}<p class="smallinfo">The imported syllabus takes priority for official policies, schedule and grading information.</p>`:'<p>Your professor has not uploaded an official Simple Syllabus yet.</p>'}</section><aside class="card"><h2>Start here</h2><div class="listrow">✦ &nbsp; Ask the assistant about course policies</div><div class="listrow">☷ &nbsp; ${fs.length} approved FAQ answers</div><div class="listrow">▧ &nbsp; ${ms.length} resources from your professor</div><div class="listrow">◷ &nbsp; ${esc(officeInfo)}</div></aside></div>`:state.studentTab==='faqs'?`<div class="card"><h2>Professor-approved answers</h2>${fs.map(f=>`<div class="listrow"><div><strong>${esc(f.question)}</strong><p class="smallinfo">${esc(f.answer)}</p></div><button class="btn ghost small" data-faqview="${f.id}">Open</button></div>`).join('')||'<div class="empty">No FAQs published yet.</div>'}</div>`:state.studentTab==='resources'?`<div class="card"><h2>Learning resources</h2>${ms.map(m=>`<div class="listrow"><div><strong>${esc(m.title)}</strong><div class="muted">${esc(m.kind.replace('_',' '))}</div></div><div class="actions">${m.url?`<a class="btn ghost small" href="${esc(m.url)}" target="_blank" rel="noopener noreferrer">Visit ↗</a>`:''}<button class="btn secondary small" data-viewmaterial="${m.id}">Details</button></div></div>`).join('')||'<div class="empty">No additional resources published yet.</div>'}</div>`:`<div class="layout"><section class="card"><h2>Office hours</h2><p>${esc(officeInfo)}</p>${slots.map(x=>`<div class="listrow"><strong>${esc(weekdays[x.weekday])} · ${clock(x.start_time)}–${clock(x.end_time)}</strong><span>${esc(x.location||x.meeting_type)}</span></div>`).join('')}${pref?.booking_url?`<a href="${esc(pref.booking_url)}" target="_blank" rel="noopener noreferrer" class="btn secondary">Book appointment ↗</a>`:''}</section><aside class="card"><h2>From the official syllabus</h2><p>${esc(src||'Refer to your professor for policy details.')}</p></aside></div>`)}
function assistant(){const cs=state.data.courses.filter(c=>state.studentCourses.includes(c.id));if(!cs.length)return heading('Course support','Course assistant','Join a class first to access its teaching assistant.',button('＋ Join class','join'));if(!cs.some(c=>c.id===state.courseId))state.courseId=cs[0].id;return heading('Course support','Ask your course assistant','Answers are based on instructor-approved FAQs and course materials.')+`<div class="two-cols"><aside class="card"><h2>Class tabs</h2><p style="font-size:12px">Select a class to ask questions about it.</p>${cs.map(c=>`<button class="course-tile ${state.courseId===c.id?'active':''}" data-chatcourse="${c.id}"><span class="course-icon">${esc((c.course_code||c.code).slice(0,2))}</span><span><strong>${esc(sectionLabel(c))}</strong><div class="muted">${esc(c.name)}</div></span></button>`).join('')}<div class="note" style="margin-top:18px">Official Simple Syllabus policies take priority. For deadlines, you can optionally match this section to Canvas in Canvas & Tasks. Other answers use approved FAQs and resources.</div></aside><section class="card chat"><div class="sectionhead"><h2>✦ ${esc(course()?.code||'')} Assistant</h2><span class="tag">${state.data.ai_enabled?'AI connected':'Knowledge search'}</span></div><div class="messages" id="messages">${state.chat.filter(m=>m.course_id===state.courseId).map(m=>`<div class="bubble ${m.who}">${esc(m.text)}${m.sources?.length?`<div class="source">▤ ${m.sources.map(esc).join(' · ')}</div>`:''}</div>`).join('')||'<div class="empty">Ask about class projects, office hours, the syllabus, or assignments.</div>'}</div><form id="chatForm" class="chatbar"><input id="chatInput" placeholder="Ask a question about this class..." required maxlength="1200"><button class="btn" type="submit" ${state.busy?'disabled':''}>${state.busy?'Thinking…':'Send ↗'}</button></form></section></div>`}
function modal(title,html){$('modalRoot').innerHTML=`<div class="modalbg"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="sectionhead"><h2>${esc(title)}</h2><button class="btn ghost small" data-action="close">✕</button></div>${html}</div></div>`}
function courseForm(){modal('Add a teaching section',`<form id="courseForm"><div class="field"><label>Course code</label><input id="newCode" placeholder="e.g. FINP 235" maxlength="30" required></div><div class="field"><label>Course name</label><input id="newName" placeholder="e.g. Foundations of Money Education" maxlength="100" required></div><div class="formgrid"><div class="field"><label>Section number</label><input id="newSection" value="001" placeholder="e.g. 598" maxlength="15" required></div><div class="field"><label>Semester</label><input id="newTerm" value="Fall 2026" required></div></div><div class="note" style="margin-bottom:14px">You can create multiple sections of FINP 235. Each section has its own syllabus, students, FAQs, and office hours.</div><button type="submit" class="btn">Create section</button></form>`)}
function materialForm(){modal('Add supplemental resource',`<form id="materialForm"><div class="field"><label>Section</label><select id="mCourse">${state.data.courses.map(c=>`<option value="${c.id}" ${c.id===state.courseId?'selected':''}>${esc(sectionLabel(c))}</option>`).join('')}</select></div><div class="field"><label>Category</label><select id="mKind">${kinds.filter(x=>x[0]!=='all').map(([id,name])=>`<option value="${id}" ${state.tab===id?'selected':''}>${name}</option>`).join('')}</select></div><div class="field"><label>Title</label><input id="mTitle" required maxlength="140" placeholder="e.g. Khan Academy practice"></div><div class="field"><label>Description or context</label><textarea id="mBody" placeholder="How this resource helps students..."></textarea></div><div class="field"><label>Optional resource URL</label><input id="mUrl" type="url" placeholder="https://..."></div><button class="btn" type="submit">Save resource</button></form>`)}
function uploadForm(){modal('Upload supplemental document',`<form id="uploadForm"><div class="field"><label>Section</label><select id="upCourse">${state.data.courses.map(c=>`<option value="${c.id}" ${c.id===state.courseId?'selected':''}>${esc(sectionLabel(c))}</option>`).join('')}</select></div><div class="field"><label>Optional PDF, TXT or MD file (32 MB max)</label><input type="file" id="upFile" required accept=".pdf,.txt,.md"></div><div class="note" style="margin-bottom:15px">For syllabi, use the separate Official Syllabus page. This upload is for supplementary documents only.</div><button class="btn" type="submit">Upload supplement</button></form>`)}
function syllabusForm(){modal('Import official Simple Syllabus',`<form id="syllabusForm"><div class="field"><label>Section</label><select id="syCourse">${state.data.courses.map(c=>`<option value="${c.id}" ${c.id===state.courseId?'selected':''}>${esc(sectionLabel(c))}</option>`).join('')}</select></div><div class="field"><label>Printed Simple Syllabus PDF (32 MB max)</label><input id="syFile" type="file" accept=".pdf" required></div><div class="field"><label>Original Simple Syllabus URL (optional)</label><input id="syUrl" type="url" placeholder="https://tamu.simplesyllabus.com/..."></div><div class="note" style="margin-bottom:16px">This official source is used first for grading policies, course schedules, deadlines, contacts and syllabus questions. The app will reject generic PDFs here.</div><button class="btn" type="submit">Import & index official syllabus</button></form>`)}
function officeForm(){modal('Schedule weekly office hours',`<form id="officeForm"><div class="field"><label>Section</label><select id="ohCourse">${state.data.courses.map(c=>`<option value="${c.id}" ${c.id===state.courseId?'selected':''}>${esc(sectionLabel(c))}</option>`).join('')}</select></div><div class="field"><label>Day of week</label><select id="ohDay">${weekdays.map((d,i)=>`<option value="${i}" ${i===state.officeDay?'selected':''}>${d}</option>`).join('')}</select></div><div class="formgrid"><div class="field"><label>Start time</label><input type="time" id="ohStart" value="14:00" required></div><div class="field"><label>End time</label><input type="time" id="ohEnd" value="15:00" required></div></div><div class="field"><label>Meeting format</label><select id="ohType"><option>In person</option><option>Virtual</option><option>Hybrid</option><option>By appointment</option></select></div><div class="field"><label>Room or meeting instructions</label><input id="ohLocation" placeholder="e.g. AGSV 250 or Zoom"></div><div class="field"><label>Booking link (optional)</label><input id="ohBooking" type="url" placeholder="https://calendly.com/..."></div><button class="btn" type="submit">Save office hours</button></form>`)}
function appointmentForm(){const pref=state.data.office_settings?.find(x=>x.course_id===state.courseId);modal('Appointment details',`<form id="appointmentForm"><div class="field"><label>Booking link (optional)</label><input type="url" id="apptUrl" placeholder="https://calendly.com/..." value="${esc(pref?.booking_url||'')}"></div><div class="field"><label>How should students schedule a meeting?</label><textarea id="apptInstructions" maxlength="1500" placeholder="e.g. Email me with two available meeting times. Include your section number.">${esc(pref?.instructions||'')}</textarea></div><div class="note" style="margin-bottom:15px">Your official syllabus remains the source for the policy; this adds convenient scheduling instructions.</div><button type="submit" class="btn">Save appointment setup</button></form>`)}
function faqForm(){modal('Add approved FAQ answer',`<form id="faqForm"><div class="field"><label>Class</label><select id="faqCourse">${state.data.courses.map(c=>`<option value="${c.id}" ${c.id===state.courseId?'selected':''}>${esc(c.code)}</option>`).join('')}</select></div><div class="field"><label>Question</label><input id="faqQuestion" placeholder="e.g. What is the late work policy?" required maxlength="300"></div><div class="field"><label>Approved answer</label><textarea id="faqAnswer" required placeholder="Write the exact answer students should receive."></textarea></div><button class="btn" type="submit">Save FAQ</button></form>`)}
function codeForm(){modal('Generate section join code',`<form id="codeForm"><div class="field"><label>Class</label><select id="codeCourse">${state.data.courses.map(c=>`<option value="${c.id}" ${c.id===state.courseId?'selected':''}>${esc(c.code)}</option>`).join('')}</select></div><div class="field"><label>Code expires in</label><select id="codeDays"><option value="1">1 day</option><option value="7" selected>7 days</option><option value="14">14 days</option><option value="30">30 days</option><option value="90">90 days</option></select></div><button class="btn" type="submit">Generate secure code</button></form>`)}
function joinForm(){modal('Join a section',`<form id="joinForm"><div class="field"><label>Your display name</label><input id="studentName" required value="${esc(state.studentName)}"></div><div class="field"><label>Class code from your professor</label><input id="joinCode" required placeholder="CP-XXXXXXXX" style="text-transform:uppercase"></div><button type="submit" class="btn">Join class</button></form>`)}
function detail(m){modal(m.title,`<span class="tag">${esc(m.kind.replace('_',' '))}</span><p style="white-space:pre-wrap;color:#40526e">${esc(m.body)}</p>${m.url?`<a href="${esc(m.url)}" target="_blank" rel="noopener noreferrer">Open resource ↗</a>`:''}`)}
function close(){ $('modalRoot').innerHTML='' }
async function mutation(path,data,success){try{await api(path,data);close();await load();toast(success)}catch(e){toast(e.message)}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-student-tab],[data-page],[data-action],[data-tab],[data-selectcourse],[data-delete],[data-revoke],[data-detail],[data-studentcourse],[data-visit],[data-chatcourse],[data-viewmaterial],[data-faqview],[data-contenttab],[data-office-mode],[data-office-day]');if(!b)return;
if(b.dataset.studentTab){state.studentTab=b.dataset.studentTab;render()}
else if(b.dataset.page){state.page=b.dataset.page;state.tab='all';render()}
else if(b.dataset.contenttab){state.contentTab=b.dataset.contenttab;if(b.dataset.openknowledge)state.page='content';render()}
else if(b.dataset.officeDay!==undefined){state.officeDay=Number(b.dataset.officeDay);render()}
else if(b.dataset.officeMode){if(b.dataset.officeMode==='appointment'){state.officeModeDraft='appointment';appointmentForm()}else{mutation('office_settings',{course_id:state.courseId,mode:'weekly',instructions:'',booking_url:''},'Weekly calendar enabled')}}
else if(b.dataset.action){const a=b.dataset.action;if(a==='close')close();if(a==='course')courseForm();if(a==='material')materialForm();if(a==='upload')uploadForm();if(a==='faq')faqForm();if(a==='code')codeForm();if(a==='join')joinForm();if(a==='syllabus')syllabusForm();if(a==='openSyllabus')goContent('syllabus');if(a==='hours')officeForm();if(a==='appointment')appointmentForm();if(a==='assistant'){state.page='assistant';render()}if(a==='canvasRefresh')syncCanvas();if(a==='canvasDisconnect'){if(confirm('Disconnect Canvas from this browser session?')){await api('canvas/disconnect',{});state.canvasStatus.connected=false;state.canvasCourses=[];state.canvasAssignments=[];render()}}}
else if(b.dataset.tab){state.tab=b.dataset.tab;render()}
else if(b.dataset.selectcourse){state.courseId=Number(b.dataset.selectcourse);state.page=b.dataset.next||'content';state.tab='all';render()}
else if(b.dataset.delete){const [kind,id]=b.dataset.delete.split(':');if(confirm('Delete this '+kind+'? This cannot be undone.'))mutation('delete',{kind,id:Number(id)},'Removed successfully')}
else if(b.dataset.revoke){if(confirm('Revoke this class code? Students will no longer be able to use it.'))mutation('revoke',{id:Number(b.dataset.revoke)},'Class code revoked')}
else if(b.dataset.detail){const m=state.data.materials.find(x=>x.id===Number(b.dataset.detail));if(m)detail(m)}
else if(b.dataset.studentcourse){state.courseId=Number(b.dataset.studentcourse);state.studentTab='overview';state.page='studentDetail';renderStudentDetail()}
else if(b.dataset.visit){state.courseId=Number(b.dataset.visit.split(':')[1]);state.page='assistant';render()}
else if(b.dataset.chatcourse){state.courseId=Number(b.dataset.chatcourse);render()}
else if(b.dataset.viewmaterial){const m=state.data.materials.find(x=>x.id===Number(b.dataset.viewmaterial));if(m){detail(m);api('activity',{course_id:m.course_id,event:'material_view',subject:m.title}).then(load).catch(()=>{})}}
else if(b.dataset.faqview){const f=state.data.faqs.find(x=>x.id===Number(b.dataset.faqview));if(f){modal(f.question,`<p>${esc(f.answer)}</p>`);api('activity',{course_id:f.course_id,event:'faq_view',subject:f.question}).then(load).catch(()=>{})}}
});
function renderStudentDetail(){nav();const c=state.data.courses.find(x=>x.id===state.courseId);$('view').innerHTML=c?studentCourse(c):student()}
document.addEventListener('change',e=>{if(e.target.dataset.mapSection){state.canvasMapping[e.target.dataset.mapSection]=e.target.value;localStorage.setItem('cp_canvas_mapping',JSON.stringify(state.canvasMapping));toast('Section mapping saved');return}if(e.target.id==='canvasCoursePicker'){canvasChoose(e.target.value);return}if(e.target.id==='courseSelect'){state.courseId=Number(e.target.value);render()}});
document.addEventListener('submit',async e=>{e.preventDefault();const id=e.target.id;
if(id==='courseForm')return mutation('course',{code:$('newCode').value,name:$('newName').value,term:$('newTerm').value,section:$('newSection').value},'Section created');
if(id==='materialForm')return mutation('material',{course_id:Number($('mCourse').value),kind:$('mKind').value,title:$('mTitle').value,body:$('mBody').value,url:$('mUrl').value},'Knowledge item saved');
if(id==='faqForm')return mutation('faq',{course_id:Number($('faqCourse').value),question:$('faqQuestion').value,answer:$('faqAnswer').value},'FAQ published');
if(id==='codeForm'){try{const x=await api('code',{course_id:Number($('codeCourse').value),days:Number($('codeDays').value)});await load();modal('Share this class code',`<p>Share this code only with students in your section.</p><div class="code-display">${esc(x.code)}</div><div class="actions" style="justify-content:center;margin:18px 0"><button class="btn" id="copyCode">Copy class code</button></div><div class="note">Expires ${fmt(x.expires_at)}. For security, the full code will not be shown again after this window closes.</div>`);$('copyCode').onclick=()=>navigator.clipboard.writeText(x.code).then(()=>toast('Code copied')).catch(()=>toast('Select the code to copy it'))}catch(err){toast(err.message)}return}
if(id==='uploadForm'){const f=$('upFile').files[0];if(!f)return;if(f.size>32000000)return toast('File must be under 32 MB');const course_id=Number($('upCourse').value);const b64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(f)});return mutation('upload',{course_id,name:f.name,base64:b64},'Document indexed')}
if(id==='syllabusForm'){const f=$('syFile').files[0];if(!f)return;if(f.size>32000000)return toast('Syllabus PDF must be under 32 MB');const course_id=Number($('syCourse').value),url=$('syUrl').value;const b64=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result.split(',')[1]);fr.onerror=reject;fr.readAsDataURL(f)});return mutation('syllabus',{course_id,name:f.name,url,base64:b64},'Official Simple Syllabus indexed')}
if(id==='appointmentForm')return mutation('office_settings',{course_id:state.courseId,mode:'appointment',instructions:$('apptInstructions').value,booking_url:$('apptUrl').value},'Appointment scheduling updated');
if(id==='officeForm')return mutation('office_hours',{course_id:Number($('ohCourse').value),weekday:Number($('ohDay').value),start_time:$('ohStart').value,end_time:$('ohEnd').value,meeting_type:$('ohType').value,location:$('ohLocation').value,booking_url:$('ohBooking').value},'Office hours scheduled');
if(id==='profileForm')return mutation('profile',Object.fromEntries(['full_name','email','department','institution','bio'].map(k=>[k,$(k).value])),'Profile saved');
if(id==='joinForm'){try{const name=$('studentName').value;const x=await api('join',{student_name:name,code:$('joinCode').value});state.studentName=name;localStorage.setItem('cp_student',name);if(!state.studentCourses.includes(x.course_id))state.studentCourses.push(x.course_id);localStorage.setItem('cp_joined',JSON.stringify(state.studentCourses));state.courseId=x.course_id;close();await load();toast('Joined '+x.name)}catch(err){toast(err.message)}return}
if(id==='chatForm'){if(state.busy)return;const q=$('chatInput').value.trim();if(!q)return;const cid=state.courseId;state.chat.push({course_id:cid,who:'user',text:q});state.busy=true;render();try{const result=await api('ask',{course_id:cid,question:q,canvas_course_id:state.canvasMapping[cid]||''});state.chat.push({course_id:cid,who:'assistant',text:result.answer,sources:result.sources});await load()}catch(err){state.chat.push({course_id:cid,who:'assistant',text:err.message});render()}finally{state.busy=false;render();const m=$('messages');if(m)m.scrollTop=m.scrollHeight}}
});
$('themeBtn').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('cp_theme',state.theme);document.documentElement.dataset.theme=state.theme;render()};
$('roleBtn').onclick=()=>{state.role=state.role==='professor'?'student':'professor';state.page=state.role==='professor'?'dashboard':'studentHome';localStorage.setItem('cp_role',state.role);render()};
window.addEventListener('keydown',e=>{if(e.key==='Escape')close()});if(new URLSearchParams(location.search).has('canvas')){const msg=new URLSearchParams(location.search).get('canvas');setTimeout(()=>toast(msg==='connected'?'Canvas connected successfully':'Canvas authorization was not completed'),700);history.replaceState({},'',location.pathname)}load();syncCanvas();
